# Generated by GitHub Copilot - Oct-25-2026
import unittest
from datetime import date, timedelta
from typing import Any
from unittest.mock import patch

from health_dashboard import _additional_health_patterns, build_dashboard_payload, build_health_pattern_history


class AdditionalHealthPatternTests(unittest.TestCase):
    """Verify descriptive product thresholds, gaps, deduplication, and historical wording."""

    def setUp(self) -> None:
        """Create one fully measured week with all signals in their usual ranges."""
        self.end = date(2026, 10, 25)
        self.days = [self.end - timedelta(days=offset) for offset in range(6, -1, -1)]
        self.states = {
            key: {day: "within" for day in self.days}
            for key in ("hrv", "restingHeartRate", "sleep")
        }
        self.values = {day: 55.0 for day in self.days}
        self.native = {"hrvSummaries": [{
            "calendarDate": self.days[1].isoformat(),
            "baseline": {"balancedLow": 50, "balancedUpper": 60},
        }]}

    def detect(self) -> dict[str, dict[str, Any]]:
        """Index today's patterns by type for focused assertions."""
        return {
            event["id"]: event
            for event in _additional_health_patterns(self.states, self.values, self.end, self.native)
        }

    def improving(self, recent: tuple[float, float, float] = (40, 41, 42)) -> None:
        """Set three low days followed by three rising values against a fixed range."""
        for day, value in zip(self.days[1:], (30, 31, 32, *recent)):
            self.states["hrv"][day] = "below" if value < 50 else "within"
            self.values[day] = value

    def test_four_short_nights_out_of_five_trigger(self) -> None:
        """Accept four or five short nights but not three."""
        for day in self.days[-4:]:
            self.states["sleep"][day] = "below"
        self.assertIn("4 of these 5", self.detect()["short-sleep"]["summary"])
        self.states["sleep"][self.days[-5]] = "below"
        self.assertIn("5 of these 5", self.detect()["short-sleep"]["summary"])
        self.states["sleep"][self.days[-1]] = "within"
        self.states["sleep"][self.days[-2]] = "within"
        self.assertNotIn("short-sleep", self.detect())

    def test_short_sleep_requires_five_measured_nights(self) -> None:
        """Do not equate a missing night with normal or short sleep."""
        for day in self.days[-4:]:
            self.states["sleep"][day] = "below"
        del self.states["sleep"][self.days[-5]]
        self.assertNotIn("short-sleep", self.detect())

    def test_heart_rate_requires_three_consecutive_high_days(self) -> None:
        """Accept three, reject two, and break a streak at a gap."""
        for day in self.days[-2:]:
            self.states["restingHeartRate"][day] = "above"
        self.assertNotIn("higher-resting-heart-rate", self.detect())
        self.states["restingHeartRate"][self.days[-3]] = "above"
        event = self.detect()["higher-resting-heart-rate"]
        self.assertIn("3 days", event["summary"])
        self.assertEqual(event["startDate"], self.days[-3].isoformat())
        del self.states["restingHeartRate"][self.days[-2]]
        self.assertNotIn("higher-resting-heart-rate", self.detect())

    def test_stability_requires_all_seven_days_and_three_signals(self) -> None:
        """Only a complete, in-range week produces a positive observation."""
        self.assertIn("steady-week", self.detect())
        for key in self.states:
            with self.subTest(key=key):
                del self.states[key][self.days[0]]
                self.assertNotIn("steady-week", self.detect())
                self.states[key][self.days[0]] = "above"
                self.assertNotIn("steady-week", self.detect())
                self.states[key][self.days[0]] = "within"
        self.assertIn("not a guarantee", self.detect()["steady-week"]["evidence"])

    def test_hrv_improvement_accepts_exact_twenty_percent_gap_closure(self) -> None:
        """Rising from 40 to 42 closes exactly 20% of a ten-unit gap."""
        self.improving()
        event = self.detect()["hrv-improving"]
        self.assertIn("40, 41, 42 ms", event["evidence"])
        self.assertEqual(event["startDate"], self.days[1].isoformat())
        self.improving((40, 41, 41.9))
        self.assertNotIn("hrv-improving", self.detect())

    def test_one_better_night_flat_values_and_overshoot_are_not_improvement(self) -> None:
        """Avoid treating noise or a jump above the range as returning toward usual."""
        for readings in ((40, 40, 45), (40, 39, 45), (40, 45, 61)):
            with self.subTest(readings=readings):
                self.improving(readings)
                self.assertNotIn("hrv-improving", self.detect())

    def test_improvement_needs_low_stretch_and_no_missing_days(self) -> None:
        """Require three classified low days and a complete three-night rise."""
        self.improving()
        self.states["hrv"][self.days[1]] = "within"
        self.assertNotIn("hrv-improving", self.detect())
        self.states["hrv"][self.days[1]] = "below"
        del self.values[self.days[-2]]
        self.assertNotIn("hrv-improving", self.detect())

    def test_improvement_uses_prior_personal_range_without_native_bounds(self) -> None:
        """A range from before the low stretch supports improvement without Garmin bounds."""
        self.improving()
        self.values.update({self.days[1] - timedelta(days=offset): 50.0 for offset in range(1, 15)})
        events = _additional_health_patterns(self.states, self.values, self.end, None)
        self.assertIn("hrv-improving", {event["id"] for event in events})
        del self.values[self.days[1] - timedelta(days=14)]
        events = _additional_health_patterns(self.states, self.values, self.end, None)
        self.assertNotIn("hrv-improving", {event["id"] for event in events})

    def test_historical_events_merge_and_do_not_give_current_advice(self) -> None:
        """Consecutive short-sleep windows become one dated past event."""
        for day in self.days:
            self.states["sleep"][day] = "below"
        with patch("health_dashboard._pattern_day_states", return_value=self.states):
            events = build_health_pattern_history({}, self.days[0], self.end + timedelta(days=4))
        short = [event for event in events if event["id"].startswith("short-sleep:")]
        self.assertEqual(len(short), 1)
        self.assertEqual(short[0]["endDate"], self.end.isoformat())
        self.assertEqual(short[0]["status"], "historical")
        self.assertIn("not advice for today", short[0]["action"])

    def test_combined_recovery_event_replaces_duplicate_heart_rate_warning(self) -> None:
        """Retain one combined warning instead of another card for the same high-heart-rate days."""
        for day in self.days[-3:]:
            self.states["hrv"][day] = "below"
            self.states["restingHeartRate"][day] = "above"
        with patch("health_dashboard._pattern_day_states", return_value=self.states):
            events = build_health_pattern_history({}, self.days[0], self.end)
        ids = [event["id"] for event in events]
        self.assertTrue(any(key.startswith("recovery-strain:") for key in ids))
        self.assertFalse(any(key.startswith("higher-resting-heart-rate:") for key in ids))

    def test_future_readings_cannot_affect_improvement(self) -> None:
        """Looking at a historical day ignores later HRV values and states."""
        self.improving()
        before = self.detect()
        tomorrow = self.end + timedelta(days=1)
        self.values[tomorrow] = 1000
        for state in self.states.values():
            state[tomorrow] = "above"
        self.assertEqual(self.detect(), before)

    def test_improvement_is_not_created_by_a_moving_comparison_range(self) -> None:
        """A changing label alone cannot establish a real move toward the fixed reference."""
        self.improving()
        self.values[self.days[1]] = 55
        self.assertNotIn("hrv-improving", self.detect())

    def test_new_patterns_reach_payload_through_real_baseline_calculations(self) -> None:
        """Exercise normalization-to-card wiring without mocking daily classifications."""
        start = self.end - timedelta(days=29)
        for target in ("steady-week", "short-sleep", "higher-resting-heart-rate", "hrv-improving"):
            with self.subTest(target=target):
                dates = [self.end - timedelta(days=offset) for offset in range(59, -1, -1)]
                hrv = {day: 50.0 for day in dates}
                heart = {day: 50.0 for day in dates}
                sleep = {day: 28800.0 for day in dates}
                if target == "short-sleep":
                    for day, hours in zip(dates[-4:], (7, 6, 5, 4)):
                        sleep[day] = hours * 3600
                elif target == "higher-resting-heart-rate":
                    for day in dates[-3:]:
                        heart[day] = 70.0
                elif target == "hrv-improving":
                    for day, value in zip(dates[-6:], (30, 31, 32, 40, 41, 42)):
                        hrv[day] = float(value)
                payload = build_dashboard_payload(
                    {
                        "hrv": {"lastNightAvg": hrv},
                        "heart_rate": {"restingValue": heart},
                        "sleep": {"sleepTimeSeconds": sleep},
                    },
                    {}, start, self.end,
                )
                matches = [event for event in payload["healthPatterns"] if event["id"].startswith(f"{target}:")]
                self.assertEqual(len(matches), 1)
                self.assertEqual(matches[0]["status"], "recent")
                self.assertEqual(matches[0]["endDate"], self.end.isoformat())
                self.assertTrue(all(
                    isinstance(matches[0][key], str)
                    for key in ("id", "title", "summary", "action", "evidence", "startDate", "endDate")
                ))
                self.assertEqual(len(payload["metrics"]["hrv"]["points"]), 30)


if __name__ == "__main__":
    unittest.main()
